@Inject(method = "setupAnim(Lnet/minecraft/client/renderer/entity/state/HumanoidRenderState;)V", at = @At("TAIL"))
private void godwand$dominionPose(net.minecraft.client.renderer.entity.state.HumanoidRenderState state, CallbackInfo ci) {
    var level = net.minecraft.client.Minecraft.getInstance().level;
    var entity = level == null ? null : level.getEntity(net.godwand.client.AtomicPoseFrames.entityId(state));
    if (entity instanceof LivingEntity living) {
        BlockDominionPose.applyLimbPose(living, net.godwand.client.AtomicPoseFrames.partial(state), head, body, rightArm, leftArm, rightLeg, leftLeg, hat);
    }
}
